{
  "python_source": "import math\nfrom typing import List, Dict, Any, Tuple\n\n# Type definitions for clarity\nOHLC = Dict[str, float]\nPreparedData = Dict[str, List[float]]\nSignalOutput = Dict[str, Any]\n\n# --- Utility Functions ---\n\ndef calculate_true_range(high: float, low: float, close_prev: float) -> float:\n    \"\"\"Calculates the True Range for a given bar.\"\"\"\n    return max(\n        high - low,\n        abs(high - close_prev),\n        abs(low - close_prev)\n    )\n\ndef calculate_sma(data: List[float], period: int) -> List[float]:\n    \"\"\"Calculates Simple Moving Average (SMA) for a list of data.\"\"\"\n    if not data or period <= 0:\n        return [0.0] * len(data)\n    \n    sma = []\n    for i in range(len(data)):\n        if i < period - 1:\n            sma.append(0.0)  # Not enough data\n        else:\n            window = data[i - period + 1 : i + 1]\n            sma.append(sum(window) / period)\n    return sma\n\ndef calculate_atr(history: List[OHLC], atr_period: int) -> List[float]:\n    \"\"\"Calculates Average True Range (ATR) using SMA.\"\"\"\n    if not history or atr_period <= 0:\n        return [0.0] * len(history)\n\n    tr_values = []\n    for i in range(len(history)):\n        if i == 0:\n            # For the first bar, use High-Low as a proxy for TR\n            tr_values.append(history[i]['High'] - history[i]['Low'])\n        else:\n            close_prev = history[i-1]['Close']\n            tr = calculate_true_range(\n                history[i]['High'], history[i]['Low'], close_prev\n            )\n            tr_values.append(tr)\n\n    # Calculate SMA of TR\n    return calculate_sma(tr_values, atr_period)\n\n# --- Strategy Implementation ---\n\ndef metadata() -> Dict[str, Any]:\n    \"\"\"Returns the metadata for the strategy.\"\"\"\n    return {\n        \"module_name\": \"Local_Strategy_Engine\",\n        \"strategy_name\": \"Exhaustion_MeanReversion_LowVol\",\n        \"description\": \"Mean reversion strategy filtered by low volatility regime, based on exhaustion candles.\"\n    }\n\ndef parameter_schema() -> Dict[str, Any]:\n    \"\"\"Defines the schema and ranges for strategy parameters.\"\"\"\n    return {\n        \"atr_period\": {\"type\": \"int\", \"description\": \"Period for ATR calculation.\", \"range\": [10, 20]},\n        \"body_multiplier\": {\"type\": \"float\", \"description\": \"Multiplier for average body size in exhaustion candle definition.\", \"range\": [1.2, 2.0]},\n        \"risk_reward_ratio\": {\"type\": \"float\", \"description\": \"Target Risk/Reward ratio (TP/SL).\", \"range\": [1.5, 3.0]}\n    }\n\ndef prepare(history: List[OHLC]) -> PreparedData:\n    \"\"\"Pre-calculates necessary indicators and features from the historical data.\"\"\"\n    if not history:\n        return {}\n\n    # Fixed periods based on candidate requirements\n    ATR_PERIOD = 14\n    ATR_MA_PERIOD = 20\n    BODY_AVG_PERIOD = 10\n\n    # 1. Calculate ATR(14)\n    atr_14 = calculate_atr(history, ATR_PERIOD)\n\n    # 2. Calculate 20-period Moving Average of ATR(14)\n    atr_14_ma_20 = calculate_sma(atr_14, ATR_MA_PERIOD)\n\n    # 3. Calculate Average Body Size (10 periods)\n    body_sizes = [abs(h['Close'] - h['Open']) for h in history]\n    avg_body_size_10 = calculate_sma(body_sizes, BODY_AVG_PERIOD)\n\n    return {\n        \"atr_14\": atr_14,\n        \"atr_14_ma_20\": atr_14_ma_20,\n        \"avg_body_size_10\": avg_body_size_10\n    }\n\ndef signal(history: List[OHLC], prepared: PreparedData, params: Dict[str, Any]) -> SignalOutput:\n    \"\"\"Generates trading signals based on the prepared data and parameters.\"\"\"\n    if not history or not prepared:\n        return {\"signal\": None, \"details\": \"Insufficient data or preparation failed.\"}\n\n    # Extract parameters\n    body_multiplier = params.get('body_multiplier', 1.5)\n    risk_reward_ratio = params.get('risk_reward_ratio', 2.0)\n\n    # Extract prepared data\n    atr_14 = prepared.get('atr_14', [])\n    atr_14_ma_20 = prepared.get('atr_14_ma_20', [])\n    avg_body_size_10 = prepared.get('avg_body_size_10', [])\n\n    # Store signals found\n    signals = []\n\n    # Iterate through the history to find exhaustion candles (Bar t)\n    # We need to check up to len(history) - 1 because we look at the next bar (t+1)\n    for t in range(len(history) - 1):\n        current_bar = history[t]\n        next_bar = history[t+1]\n        \n        # --- Step 1: Volatility Filter Check (Low Volatility Regime) ---\n        # Condition: ATR(14) < 20-period moving average of ATR(14)\n        if atr_14[t] >= atr_14_ma_20[t]:\n            continue # Regime not met\n\n        # --- Step 2: Exhaustion Candle Check (Bar t) ---\n        \n        # Calculate body size and range\n        body_size = abs(current_bar['Close'] - current_bar['Open'])\n        range_size = current_bar['High'] - current_bar['Low']\n        \n        if range_size == 0:\n            continue\n\n        # Check body size condition\n        is_large_body = body_size > body_multiplier * avg_body_size_10[t]\n        \n        # Check candle type and relative size (small body relative to range)\n        \n        # Bullish exhaustion: small body, positive close, large body size\n        is_bullish_exhaustion = (\n            (current_bar['Close'] - current_bar['Open']) / range_size < 0.2 and \n            (current_bar['Close'] - current_bar['Open']) > 0 and \n            is_large_body\n        )\n        \n        # Bearish exhaustion: small body, negative close, large body size\n        is_bearish_exhaustion = (\n            (current_bar['Open'] - current_bar['Close']) / range_size < 0.2 and \n            (current_bar['Open'] - current_bar['Close']) > 0 and \n            is_large_body\n        )\n\n        if not (is_bullish_exhaustion or is_bearish_exhaustion):\n            continue # Not an exhaustion candle\n\n        # --- Step 3: Breakout Check (Bar t+1) ---\n        signal_type = None\n        entry_price = None\n        \n        if is_bearish_exhaustion:\n            # Long entry: Exhaustion candle is bearish, price breaks above High of exhaustion candle\n            if next_bar['High'] > current_bar['High']:\n                signal_type = 'LONG'\n                entry_price = next_bar['Open'] # Assuming entry at next bar open\n        \n        elif is_bullish_exhaustion:\n            # Short entry: Exhaustion candle is bullish, price breaks below Low of exhaustion candle\n            if next_bar['Low'] < current_bar['Low']:\n                signal_type = 'SHORT'\n                entry_price = next_bar['Open'] # Assuming entry at next bar open\n\n        if signal_type:\n            # --- Step 4 & 5: Calculate SL/TP and Execute Trade ---\n            \n            # Risk calculation based on ATR(14) at the signal bar (t+1)\n            atr_current = atr_14[t+1] \n            \n            # Stop Loss distance = 1.5 * ATR(14)\n            sl_distance = 1.5 * atr_current\n            \n            # Take Profit distance = Risk * RRR\n            tp_distance = sl_distance * risk_reward_ratio\n            \n            if signal_type == 'LONG':\n                sl_price = entry_price - sl_distance\n                tp_price = entry_price + tp_distance\n            else: # SHORT\n                sl_price = entry_price + sl_distance\n                tp_price = entry_price - tp_distance\n\n            signals.append({\n                \"bar_index\": t + 1, \n                \"signal\": signal_type,\n                \"entry_price\": entry_price,\n                \"stop_loss\": sl_price,\n                \"take_profit\": tp_price,\n                \"details\": f\"Exhaustion ({'Bearish' if is_bearish_exhaustion else 'Bullish'}) followed by breakout. ATR={atr_current:.4f}\"\n            })\n\n    return {\"signals\": signals}"
}
